CREATE TYPE "ConfigurationVersionStatus" AS ENUM ('DRAFT','APPROVED','PUBLISHED','SUPERSEDED','ROLLED_BACK');
CREATE TYPE "ConfigurationApprovalDecision" AS ENUM ('APPROVED','REJECTED');
CREATE TABLE "configuration_sets" ("configurationSetId" UUID NOT NULL DEFAULT gen_random_uuid(),"scopeKey" TEXT NOT NULL,"examId" TEXT NOT NULL,"subjectId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "configuration_sets_pkey" PRIMARY KEY ("configurationSetId"),CONSTRAINT "configuration_sets_exam_fkey" FOREIGN KEY ("examId") REFERENCES "academic_exams"("canonicalId") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "configuration_sets_subject_fkey" FOREIGN KEY ("subjectId") REFERENCES "academic_subjects"("canonicalId") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "configuration_sets_examId_subjectId_key" ON "configuration_sets"("examId","subjectId"); CREATE UNIQUE INDEX "configuration_sets_scopeKey_key" ON "configuration_sets"("scopeKey");
CREATE TABLE "configuration_versions" ("configurationVersionId" UUID NOT NULL DEFAULT gen_random_uuid(),"configurationSetId" UUID NOT NULL,"versionNumber" INTEGER NOT NULL,"status" "ConfigurationVersionStatus" NOT NULL DEFAULT 'DRAFT',"createdByUserId" UUID NOT NULL,"reason" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "configuration_versions_pkey" PRIMARY KEY ("configurationVersionId"),CONSTRAINT "configuration_versions_set_fkey" FOREIGN KEY ("configurationSetId") REFERENCES "configuration_sets"("configurationSetId") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "configuration_versions_user_fkey" FOREIGN KEY ("createdByUserId") REFERENCES "users"("userId") ON DELETE RESTRICT ON UPDATE CASCADE); CREATE UNIQUE INDEX "configuration_versions_set_version_key" ON "configuration_versions"("configurationSetId","versionNumber"); CREATE INDEX "configuration_versions_set_status_idx" ON "configuration_versions"("configurationSetId","status");
CREATE TABLE "configuration_changes" ("configurationChangeId" UUID NOT NULL DEFAULT gen_random_uuid(),"configurationVersionId" UUID NOT NULL,"changeKey" TEXT NOT NULL,"beforeValue" JSONB,"afterValue" JSONB NOT NULL,"actorUserId" UUID NOT NULL,"reason" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "configuration_changes_pkey" PRIMARY KEY ("configurationChangeId"),CONSTRAINT "configuration_changes_version_fkey" FOREIGN KEY ("configurationVersionId") REFERENCES "configuration_versions"("configurationVersionId") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "configuration_changes_user_fkey" FOREIGN KEY ("actorUserId") REFERENCES "users"("userId") ON DELETE RESTRICT ON UPDATE CASCADE); CREATE UNIQUE INDEX "configuration_changes_version_key_key" ON "configuration_changes"("configurationVersionId","changeKey");
CREATE TABLE "configuration_approvals" ("configurationApprovalId" UUID NOT NULL DEFAULT gen_random_uuid(),"configurationVersionId" UUID NOT NULL,"actorUserId" UUID NOT NULL,"decision" "ConfigurationApprovalDecision" NOT NULL,"reason" TEXT NOT NULL,"correlationId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "configuration_approvals_pkey" PRIMARY KEY ("configurationApprovalId"),CONSTRAINT "configuration_approvals_version_fkey" FOREIGN KEY ("configurationVersionId") REFERENCES "configuration_versions"("configurationVersionId") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "configuration_approvals_user_fkey" FOREIGN KEY ("actorUserId") REFERENCES "users"("userId") ON DELETE RESTRICT ON UPDATE CASCADE); CREATE UNIQUE INDEX "configuration_approvals_version_user_key" ON "configuration_approvals"("configurationVersionId","actorUserId");
CREATE TABLE "configuration_publications" ("configurationPublicationId" UUID NOT NULL DEFAULT gen_random_uuid(),"configurationVersionId" UUID NOT NULL,"actorUserId" UUID NOT NULL,"previousVersionId" UUID,"reason" TEXT NOT NULL,"correlationId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "configuration_publications_pkey" PRIMARY KEY ("configurationPublicationId"),CONSTRAINT "configuration_publications_version_fkey" FOREIGN KEY ("configurationVersionId") REFERENCES "configuration_versions"("configurationVersionId") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "configuration_publications_user_fkey" FOREIGN KEY ("actorUserId") REFERENCES "users"("userId") ON DELETE RESTRICT ON UPDATE CASCADE); CREATE UNIQUE INDEX "configuration_publications_version_key" ON "configuration_publications"("configurationVersionId");
CREATE TABLE "configuration_rollbacks" ("configurationRollbackId" UUID NOT NULL DEFAULT gen_random_uuid(),"sourceVersionId" UUID NOT NULL,"targetVersionId" UUID NOT NULL,"actorUserId" UUID NOT NULL,"reason" TEXT NOT NULL,"correlationId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "configuration_rollbacks_pkey" PRIMARY KEY ("configurationRollbackId"),CONSTRAINT "configuration_rollbacks_source_fkey" FOREIGN KEY ("sourceVersionId") REFERENCES "configuration_versions"("configurationVersionId") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "configuration_rollbacks_target_fkey" FOREIGN KEY ("targetVersionId") REFERENCES "configuration_versions"("configurationVersionId") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "configuration_rollbacks_user_fkey" FOREIGN KEY ("actorUserId") REFERENCES "users"("userId") ON DELETE RESTRICT ON UPDATE CASCADE); CREATE UNIQUE INDEX "configuration_rollbacks_idempotency_key" ON "configuration_rollbacks"("sourceVersionId","targetVersionId","correlationId");
